ALTER TABLE "system_settings" ADD COLUMN "wizard_completed_at" TIMESTAMPTZ(3), ADD COLUMN "wizard_choice" TEXT;
ALTER TABLE "system_settings" ADD CONSTRAINT "wizard_choice_valid" CHECK (("wizard_completed_at" IS NULL AND "wizard_choice" IS NULL) OR ("wizard_completed_at" IS NOT NULL AND "wizard_choice" IS NOT NULL AND "wizard_choice" IN ('TECH','SALES','BOTH')));
CREATE TABLE "wizard_activations" ("id" UUID PRIMARY KEY, "settings_id" UUID NOT NULL UNIQUE REFERENCES "system_settings"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "draft_id" UUID NOT NULL UNIQUE REFERENCES "setup_drafts"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "actor_id" UUID NOT NULL REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "request_hash" TEXT NOT NULL, "request_digest" TEXT NOT NULL, "result" JSONB NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "wizard_activations_actor_id_request_hash_key" ON "wizard_activations"("actor_id","request_hash");
CREATE TABLE "setup_outbox" ("id" UUID PRIMARY KEY, "activation_id" UUID NOT NULL UNIQUE REFERENCES "wizard_activations"("id") ON DELETE RESTRICT ON UPDATE CASCADE, "topic" TEXT NOT NULL CHECK ("topic"='SETUP_ACTIVATED'), "payload" JSONB NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "dispatched_at" TIMESTAMPTZ(3));
